/* @autogenerated */

/** Nombres por los que se puede reconocer un campo en las cabeceras. */
export interface MatchCandidate {
  field: string;
  names: string[];
}

/** Puntuación mínima para proponer una cabecera; por debajo la columna queda sin emparejar. */
export const MATCH_THRESHOLD = 0.6;

/** Minúsculas, sin acentos y con cualquier separador (espacio, guion, camelCase…) como un único espacio. */
export function normalizeHeader(text: unknown): string {
  return String(text ?? '')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** Parecido entre 0 y 1: 1 si coinciden normalizados; si no, coeficiente de Dice sobre bigramas. */
export function similarity(one: unknown, other: unknown): number {
  const a = normalizeHeader(one);
  const b = normalizeHeader(other);
  if (!a || !b) {
    return 0;
  }
  if (a === b) {
    return 1;
  }
  const compactA = a.replace(/ /g, '');
  const compactB = b.replace(/ /g, '');
  if (compactA === compactB) {
    return 0.95;
  }
  const dice = diceCoefficient(compactA, compactB);
  // "correo" frente a "correo electrónico": una contiene a la otra como palabras completas
  const contained = ` ${a} `.includes(` ${b} `) || ` ${b} `.includes(` ${a} `) ? 0.75 : 0;
  return Math.max(dice, contained);
}

/**
 * Propone una cabecera para cada campo: se asignan primero las parejas más parecidas y cada cabecera
 * se usa una sola vez. Devuelve la posición de la cabecera, o `null` si ninguna supera el umbral.
 */
export function matchColumns(
  headers: string[],
  candidates: MatchCandidate[],
  threshold = MATCH_THRESHOLD,
): Record<string, number | null> {
  const pairs: { field: string; index: number; score: number }[] = [];
  candidates.forEach((candidate) => {
    headers.forEach((header, index) => {
      const score = Math.max(0, ...candidate.names.map((name) => similarity(header, name)));
      if (score >= threshold) {
        pairs.push({ field: candidate.field, index, score });
      }
    });
  });
  pairs.sort((x, y) => y.score - x.score);
  const result: Record<string, number | null> = Object.fromEntries(candidates.map((c) => [c.field, null]));
  const used = new Set<number>();
  pairs.forEach(({ field, index }) => {
    if (result[field] === null && !used.has(index)) {
      result[field] = index;
      used.add(index);
    }
  });
  return result;
}

function diceCoefficient(a: string, b: string): number {
  if (a.length < 2 || b.length < 2) {
    return 0;
  }
  const bigrams = new Map<string, number>();
  for (let i = 0; i < a.length - 1; i++) {
    const bigram = a.substring(i, i + 2);
    bigrams.set(bigram, (bigrams.get(bigram) ?? 0) + 1);
  }
  let shared = 0;
  for (let i = 0; i < b.length - 1; i++) {
    const bigram = b.substring(i, i + 2);
    const count = bigrams.get(bigram) ?? 0;
    if (count > 0) {
      bigrams.set(bigram, count - 1);
      shared++;
    }
  }
  return (2 * shared) / (a.length + b.length - 2);
}
